package dk.jamesbabz.madkursus.outbound.recipe.details;
import java.util.*; import jakarta.persistence.*; import lombok.Getter; import lombok.NoArgsConstructor; import dk.jamesbabz.madkursus.service.models.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;
@Entity @Table(name="recipe_steps") @Getter @NoArgsConstructor(access=lombok.AccessLevel.PROTECTED)
public class RecipeStepEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) @JoinColumn(name="recipe_id") private RecipeEntity recipe; @Enumerated(EnumType.STRING) private RecipeStepType stepType; private String instruction;@JdbcTypeCode(SqlTypes.JSON) private RecipeStructuredInstruction structuredInstruction; private int sortOrder; private UUID cookingProcessId; @OneToMany(mappedBy="recipeStep",cascade=CascadeType.ALL,orphanRemoval=true) private List<RecipeProcessBindingEntity> bindings=new ArrayList<>(); public RecipeStepEntity(UUID id,RecipeStepType type,String instruction,int sortOrder,UUID cookingProcessId){this(id,type,instruction,null,sortOrder,cookingProcessId);}public RecipeStepEntity(UUID id,RecipeStepType type,String instruction,RecipeStructuredInstruction structured,int sortOrder,UUID cookingProcessId){this.id=id;this.stepType=type;this.instruction=instruction;this.structuredInstruction=structured;this.sortOrder=sortOrder;this.cookingProcessId=cookingProcessId;} public RecipeStepEntity(UUID id,String instruction,int sortOrder){this(id,RecipeStepType.TEXT,instruction,sortOrder,null);} void setRecipe(RecipeEntity recipe){this.recipe=recipe;} public void addBinding(RecipeProcessBindingEntity binding){bindings.add(binding);binding.setRecipeStep(this);}}
